async function commitNoteWrite(slug, header, body, verb) {
  const mutation = await content.updateRaw(slug, header + body);
  if (!mutation) return null;
  const relPath = git.kbRelPath(mutation.fsPath);
  return {
    slug: mutation.slug,
    path: relPath,
    commit: await git.commitFiles([mutation.fsPath], `${verb} ${relPath} via mcp`)
  };
}
server.registerTool(
  "kb_add_agent_note",
  {
    title: "Leave an Agent Note",
    description: "Leave a note of your own on one passage of a page: a short explanation, anchored to the words it is about and shown to the reader in place, in pink, as yours. This is how you say why a page reads the way it does \u2014 after an edit whose reason a diff will not show (why a figure changed, what you could not verify, which of two readings you took), or to flag something you noticed and were not asked to change. `quote` is the text to anchor to, copied as a reader sees it: plain words with no Markdown markup, from inside a single paragraph, list, heading, table or code block \u2014 kb_get_page returns the source to copy from. A quote that is not found, or that appears in more than one block, is refused rather than guessed at. `text` is required, unlike a human highlight: a pink mark with nothing written on it explains nothing. Leave one note per thing actually worth saying, not one per paragraph \u2014 a page fenced in pink marks is one nobody reads. A person can resolve your note but never edit it, so write it to be read once and taken down; take down your own with kb_resolve_agent_note.",
    inputSchema: {
      slug: string2().describe("Page slug, e.g. engineering/runbooks/deploy."),
      quote: string2().min(1).describe(
        "The passage to anchor the note to, as a reader sees it. Must appear in exactly one block of the page."
      ),
      text: string2().min(1).describe("The note itself \u2014 what the reader should know here."),
      spaceInstructionsToken: instructionTokenSchema
    },
    annotations: {
      readOnlyHint: false,
      openWorldHint: false
    }
  },
  async ({ slug, quote, text: text2, spaceInstructionsToken }) => {
    const refused = refuseInstructionsPath(slug);
    if (refused) return refused;
    const spaceKey = content.spaceKeyOf(slug);
    const gate = await gateWrite(spaceKey, spaceInstructionsToken);
    if (gate) return gate;
    try {
      const page = await content.loadRaw(slug);
      if (!page) return errorResult(`Page not found: ${cleanSlug3(slug) || "(home)"}`);
      const { header, body } = splitFrontmatter(page.raw);
      const written = addAgentNote(body, { quote, text: text2, author: NOTE_AUTHOR });
      if (!written.ok) return errorResult(written.error);
      if (!written.added) {
        return textResult({
          added: false,
          reason: "An identical note is already on that passage.",
          slug: cleanSlug3(slug),
          path: git.kbRelPath(page.fsPath),
          noteId: written.note.id,
          quote: written.note.quote,
          ...await writeToken(spaceKey)
        });
      }
      const mutation = await commitNoteWrite(slug, header, written.body, "Add note to");
      if (!mutation) return errorResult(`Page not found: ${cleanSlug3(slug) || "(home)"}`);
      return textResult({
        added: true,
        ...mutation,
        noteId: written.note.id,
        // The quote as stored, which is the page's own text: markup resolved
        // away and punctuation smartened, so it can be found again in the
        // rendered page. It may not be the string that was passed in.
        quote: written.note.quote,
        line: written.note.line,
        ...await writeToken(spaceKey)
      });
    } catch (err) {
      return errorResult(errorMessage(err));
    }
  }
);
